CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW."updatedAt" = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_username text;
  v_full_name text;
  v_university_id text;
begin
  v_username := nullif(trim(new.raw_user_meta_data->>'username'), '');
  if v_username is null then
    v_username := split_part(new.email, '@', 1) || '_' || right(new.id::text, 6);
  end if;

  v_full_name := nullif(trim(new.raw_user_meta_data->>'full_name'), '');
  if v_full_name is null then
    v_full_name := initcap(replace(split_part(new.email, '@', 1), '.', ' '));
  end if;

  v_university_id := nullif(new.raw_user_meta_data->>'universityId', '');
  if v_university_id is not null
     and not exists (select 1 from public."University" u where u.id = v_university_id) then
    v_university_id := null;
  end if;

  insert into public."Profile" (id, email, "fullName", username, "universityId", role, "updatedAt")
  values (new.id, new.email, v_full_name, v_username, v_university_id, 'STUDENT', now())
  on conflict (id) do update
  set email = excluded.email,
      "fullName" = excluded."fullName",
      username = excluded.username,
      "universityId" = excluded."universityId",
      "updatedAt" = now();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_application_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO "ApplicationStatusHistory"("applicationId", "fromStatus", "toStatus")
    VALUES (NEW.id, OLD.status, NEW.status);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.review_university_request(p_university_id text, p_new_status "UniversityStatus", p_review_note text DEFAULT NULL::text)
 RETURNS TABLE(id text, status "UniversityStatus")
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from_status "UniversityStatus";
  v_id text;
  v_status "UniversityStatus";
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- FIX: was am_i_admin(); now is_platform_admin() to require role='ADMIN' AND universityId IS NULL
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Platform admin privileges required';
  END IF;

  IF p_new_status NOT IN ('APPROVED'::"UniversityStatus", 'REJECTED'::"UniversityStatus") THEN
    RAISE EXCEPTION 'Invalid target status: %', p_new_status;
  END IF;

  SELECT u.status
  INTO v_from_status
  FROM "University" u
  WHERE u.id = p_university_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'University not found';
  END IF;

  IF v_from_status <> 'PENDING'::"UniversityStatus" THEN
    RAISE EXCEPTION 'Only pending universities can be reviewed';
  END IF;

  UPDATE "University"
  SET
    status = p_new_status,
    "updatedAt" = now()
  WHERE "University".id = p_university_id
  RETURNING "University".id, "University".status INTO v_id, v_status;

  INSERT INTO "UniversityStatusHistory"(
    "universityId",
    "fromStatus",
    "toStatus",
    "reviewedBy",
    note
  )
  VALUES (
    p_university_id,
    v_from_status,
    v_status,
    (auth.uid())::text,
    nullif(trim(p_review_note), '')
  );

  RETURN QUERY SELECT v_id, v_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_conversation_messages_read(p_conversation_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_updated_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.check_conversation_access(p_conversation_id) THEN
    RAISE EXCEPTION 'Conversation access required';
  END IF;

  UPDATE "Message"
  SET "readBy" = CASE
    WHEN (auth.uid())::text = ANY(COALESCE("readBy", ARRAY[]::text[])) THEN COALESCE("readBy", ARRAY[]::text[])
    ELSE array_append(COALESCE("readBy", ARRAY[]::text[]), (auth.uid())::text)
  END
  WHERE "conversationId" = p_conversation_id
    AND "senderId" <> (auth.uid())::text
    AND NOT ((auth.uid())::text = ANY(COALESCE("readBy", ARRAY[]::text[])));

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  RETURN v_updated_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_platform_admin(p_target_user_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Platform admin privileges required';
  END IF;

  UPDATE "Profile"
  SET role = 'ADMIN'::"UserRole",
      "universityId" = NULL,
      "updatedAt" = now()
  WHERE id = p_target_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Target user not found';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_platform_admin(p_target_user_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Platform admin privileges required';
  END IF;

  IF p_target_user_id = (auth.uid())::text THEN
    RAISE EXCEPTION 'You cannot revoke yourself';
  END IF;

  UPDATE "Profile"
  SET role = 'STUDENT'::"UserRole",
      "updatedAt" = now()
  WHERE id = p_target_user_id
    AND role = 'ADMIN'::"UserRole"
    AND "universityId" IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Target platform admin not found';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.start_direct_conversation(p_peer_id text, p_peer_status "ConversationStatus" DEFAULT 'PENDING'::"ConversationStatus")
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_self_id text;
  v_existing_id text;
  v_new_id text;
BEGIN
  v_self_id := (auth.uid())::text;

  IF v_self_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_peer_id IS NULL OR p_peer_id = '' THEN
    RAISE EXCEPTION 'Peer user id required';
  END IF;

  IF p_peer_id = v_self_id THEN
    RAISE EXCEPTION 'Cannot start a conversation with yourself';
  END IF;

  -- Reuse an existing 1-1 conversation between the two users if one exists.
  SELECT c.id INTO v_existing_id
  FROM "Conversation" c
  WHERE c."isGroup" = false
    AND EXISTS (
      SELECT 1 FROM "ConversationParticipant" p1
      WHERE p1."conversationId" = c.id AND p1."userId" = v_self_id
    )
    AND EXISTS (
      SELECT 1 FROM "ConversationParticipant" p2
      WHERE p2."conversationId" = c.id AND p2."userId" = p_peer_id
    )
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RETURN v_existing_id;
  END IF;

  INSERT INTO "Conversation" ("isGroup", "createdBy", "updatedAt")
  VALUES (false, v_self_id, now())
  RETURNING id INTO v_new_id;

  INSERT INTO "ConversationParticipant" ("conversationId", "userId", "role", "status")
  VALUES (v_new_id, v_self_id, 'ADMIN', 'ACCEPTED');

  INSERT INTO "ConversationParticipant" ("conversationId", "userId", "role", "status")
  VALUES (v_new_id, p_peer_id, 'MEMBER', p_peer_status);

  RETURN v_new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_university_admin(p_target_user_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_university_id text;
  v_target_is_super boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT is_university_super_admin() THEN
    RAISE EXCEPTION 'University super admin privileges required';
  END IF;

  IF p_target_user_id = (auth.uid())::text THEN
    RAISE EXCEPTION 'You cannot revoke yourself';
  END IF;

  SELECT p."universityId"
  INTO v_actor_university_id
  FROM "Profile" p
  WHERE p.id = (auth.uid())::text;

  SELECT coalesce(uar."isSuper", false)
  INTO v_target_is_super
  FROM "UniversityAdminRole" uar
  WHERE uar."userId" = p_target_user_id
    AND uar."universityId" = v_actor_university_id;

  IF v_target_is_super THEN
    RAISE EXCEPTION 'Super admins cannot be revoked by university admins';
  END IF;

  UPDATE "Profile"
  SET role = 'STUDENT'::"UserRole",
      "updatedAt" = now()
  WHERE id = p_target_user_id
    AND role = 'ADMIN'::"UserRole"
    AND "universityId" = v_actor_university_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Target university admin not found in your university';
  END IF;

  DELETE FROM "UniversityAdminRole"
  WHERE "userId" = p_target_user_id
    AND "universityId" = v_actor_university_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_university_super_admin(p_target_user_id text, p_university_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Platform admin privileges required';
  END IF;

  -- Ensure target is a university admin in the target university
  IF NOT EXISTS (
    SELECT 1 FROM "Profile" p
    WHERE p.id = p_target_user_id
      AND p.role = 'ADMIN'::"UserRole"
      AND p."universityId" = p_university_id
  ) THEN
    RAISE EXCEPTION 'Target user must already be a university admin of the specified university';
  END IF;

  INSERT INTO "UniversityAdminRole"("userId", "universityId", "isSuper")
  VALUES (p_target_user_id, p_university_id, true)
  ON CONFLICT ("userId") DO UPDATE
  SET "universityId" = EXCLUDED."universityId",
      "isSuper" = true;
END;
$function$

CREATE OR REPLACE FUNCTION public.increment_thread_view_count(p_thread_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF EXISTS (SELECT 1 FROM "ForumThread" WHERE id = p_thread_id) THEN
    UPDATE "ForumThread" SET "viewCount" = COALESCE("viewCount", 0) + 1 WHERE id = p_thread_id;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_study_group_chat_access(p_group_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id text;
  v_conversation_id text;
  v_member_role text;
BEGIN
  v_user_id := (auth.uid())::text;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Verify the caller is a member of the study group
  SELECT sgm.role INTO v_member_role
  FROM "StudyGroupMember" sgm
  WHERE sgm."studyGroupId" = p_group_id
    AND sgm."userId" = v_user_id;

  IF v_member_role IS NULL THEN
    RAISE EXCEPTION 'You are not a member of this study group';
  END IF;

  -- Get the linked conversation; nothing to do if there isn't one yet
  SELECT sg."conversationId" INTO v_conversation_id
  FROM "StudyGroup" sg
  WHERE sg.id = p_group_id;

  IF v_conversation_id IS NULL THEN
    RETURN;
  END IF;

  -- Add as ACCEPTED participant if not already present
  INSERT INTO "ConversationParticipant" ("conversationId", "userId", "role", "status")
  VALUES (
    v_conversation_id,
    v_user_id,
    (CASE WHEN v_member_role = 'ADMIN' THEN 'ADMIN' ELSE 'MEMBER' END)::"ParticipantRole",
    'ACCEPTED'::"ConversationStatus"
  )
  ON CONFLICT DO NOTHING;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_profile_university_domain()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  email_domain text;
  matched_university_id text;
  matched_university_name text;
BEGIN
  IF NEW."email" IS NULL THEN
    RETURN NEW;
  END IF;

  -- Platform admins are global; keep them unscoped from any single university.
  IF NEW.role = 'ADMIN'::"UserRole" AND NEW."universityId" IS NULL THEN
    NEW."universityName" := NULL;
    RETURN NEW;
  END IF;

  email_domain := lower(split_part(NEW."email", '@', 2));

  SELECT u.id, u."name"
  INTO matched_university_id, matched_university_name
  FROM public."University" u
  WHERE u.status = 'APPROVED'
    AND EXISTS (
      SELECT 1
      FROM unnest(u.domains) AS d(domain)
      WHERE lower(d.domain) = email_domain
    )
  ORDER BY u."createdAt" ASC
  LIMIT 1;

  -- If university isn't provided, auto-assign from domain when possible.
  IF NEW."universityId" IS NULL THEN
    IF matched_university_id IS NOT NULL THEN
      NEW."universityId" := matched_university_id;
      NEW."universityName" := matched_university_name;
    END IF;
    RETURN NEW;
  END IF;

  -- If university is provided manually, it must match domain-derived university.
  IF matched_university_id IS NULL OR NEW."universityId" <> matched_university_id THEN
    RAISE EXCEPTION 'universityId does not match email domain';
  END IF;

  NEW."universityName" := matched_university_name;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prepare_study_group_chat(p_group_id text, p_conversation_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id text;
  v_member_role text;
  v_existing_conv_id text;
BEGIN
  v_user_id := (auth.uid())::text;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Verify caller is a member of the group
  SELECT sgm.role INTO v_member_role
  FROM "StudyGroupMember" sgm
  WHERE sgm."studyGroupId" = p_group_id
    AND sgm."userId" = v_user_id;

  IF v_member_role IS NULL THEN
    RAISE EXCEPTION 'You are not a member of this study group';
  END IF;

  -- Verify the conversation exists (sanity)
  IF NOT EXISTS (SELECT 1 FROM "Conversation" WHERE id = p_conversation_id) THEN
    RAISE EXCEPTION 'Conversation not found';
  END IF;

  -- Backfill StudyGroup.conversationId if missing. If it's already set to a
  -- different conversation, do nothing (don't clobber).
  SELECT sg."conversationId" INTO v_existing_conv_id
  FROM "StudyGroup" sg
  WHERE sg.id = p_group_id;

  IF v_existing_conv_id IS NULL THEN
    UPDATE "StudyGroup" SET "conversationId" = p_conversation_id WHERE id = p_group_id;
  END IF;

  -- Add caller as ACCEPTED participant (idempotent)
  INSERT INTO "ConversationParticipant" ("conversationId", "userId", "role", "status")
  VALUES (
    p_conversation_id,
    v_user_id,
    (CASE WHEN v_member_role = 'ADMIN' THEN 'ADMIN' ELSE 'MEMBER' END)::"ParticipantRole",
    'ACCEPTED'::"ConversationStatus"
  )
  ON CONFLICT DO NOTHING;
END;
$function$
